        _parts: &axum::http::request::Parts,
        session: Arc<dyn Session>,
        cancel: CancellationToken,
    ) -> Result<RunContext<Ctx>, ServerError> {
        Ok(RunContext::ephemeral(Ctx::default())
            .with_session(session)
            .with_cancel(cancel))
    }
}

